    assert_eq!(s.err(json!({"Command": "CreateQueue", "QueueName": ""})), "QueueNameInvalid");
    assert_eq!(s.err(json!({"Command": "CreateQueue", "QueueName": "a.fifo"})), "QueueNameInvalid");
    assert_eq!(
