}

#[test]
fn empty_trailing_line_is_not_a_command() {
    let mut out = Vec::new();
    serve(&b"{\"Command\":\"Tick\",\"Seconds\":1}\n"[..], &mut out).unwrap();
    assert_eq!(out.iter().filter(|&&b| b == b'\n').count(), 1);
}

