            let sent_at = message.sent_at;
            let sequence = queue.push(Message {
                receive_count: 0,
                first_received_at: None,
                delayed_until: 0,
                in_flight_until: 0,
                receipt: None,
                ..message
            });
            if now >= sent_at + retention {
                queue.messages.remove(&sequence);
            }
        }
    }

