mod common;

use common::Session;
use serde_json::{json, Value};

fn send(s: &mut Session, queue: &str, body: &str) -> Value {
    s.ok(json!({"Command": "SendMessage", "QueueName": queue, "Body": body}))
}

fn receive(s: &mut Session, queue: &str, max: u32) -> Vec<Value> {
    let r = s.ok(json!({"Command": "ReceiveMessage", "QueueName": queue, "MaxMessages": max}));
    r["Messages"].as_array().unwrap().clone()
}

fn bodies(messages: &[Value]) -> Vec<&str> {
    messages.iter().map(|m| m["Body"].as_str().unwrap()).collect()
}

fn fifo_send(s: &mut Session, queue: &str, group: &str, dedup: &str, body: &str) -> Value {
    s.ok(json!({"Command": "SendMessage", "QueueName": queue, "Body": body,
                "GroupId": group, "DeduplicationId": dedup}))
}

#[test]
fn ids_and_receive_shape_on_a_standard_queue() {
    let mut s = Session::new();
    s.create("a", json!({}));
    s.create("b", json!({}));
    assert_eq!(send(&mut s, "a", "one")["MessageId"], "m-1");
    assert_eq!(send(&mut s, "b", "two")["MessageId"], "m-2");
    assert!(send(&mut s, "a", "three").get("SequenceNumber").is_none());
    s.tick(7);
    let got = receive(&mut s, "a", 10);
    assert_eq!(
        got[0],
        json!({"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "one", "ReceiveCount": 1,
               "SentAt": 0, "FirstReceivedAt": 7})
    );
    assert_eq!(got[1]["MessageId"], "m-3");
    assert_eq!(got[1]["ReceiptHandle"], "r-2");
    // A failed send uses up no id.
    assert_eq!(s.err(json!({"Command": "SendMessage", "QueueName": "a", "Body": ""})), "InvalidParameterValue");
    assert_eq!(send(&mut s, "a", "four")["MessageId"], "m-4");
}

#[test]
fn send_validation_order() {
    let mut s = Session::new();
    s.create("a", json!({}));
    s.create("f.fifo", json!({"Fifo": true}));
    let c = |v: Value| {
        let mut m = json!({"Command": "SendMessage"});
        m.as_object_mut().unwrap().extend(v.as_object().unwrap().clone());
        m
    };
    assert_eq!(s.err(c(json!({"Body": "x"}))), "MissingParameter");
    assert_eq!(s.err(c(json!({"QueueName": "nope"}))), "MissingParameter");
    assert_eq!(s.err(c(json!({"QueueName": "nope", "Body": 1}))), "InvalidParameterValue");
    assert_eq!(s.err(c(json!({"QueueName": "nope", "Body": "x"}))), "QueueDoesNotExist");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x".repeat(1025)}))), "InvalidParameterValue");
    s.ok(c(json!({"QueueName": "a", "Body": "é".repeat(512)})));
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "é".repeat(513)}))), "InvalidParameterValue");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x", "DelaySeconds": 901}))), "InvalidParameterValue");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x", "GroupId": "a b"}))), "InvalidParameterValue");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x", "GroupId": ""}))), "InvalidParameterValue");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x", "GroupId": "g"}))), "UnsupportedOperation");
    assert_eq!(s.err(c(json!({"QueueName": "a", "Body": "x", "DeduplicationId": "g"}))), "UnsupportedOperation");
    assert_eq!(s.err(c(json!({"QueueName": "f.fifo", "Body": "x", "DelaySeconds": 0, "GroupId": "g"}))), "UnsupportedOperation");
    assert_eq!(s.err(c(json!({"QueueName": "f.fifo", "Body": "x", "DeduplicationId": "d"}))), "MissingParameter");
    assert_eq!(s.err(c(json!({"QueueName": "f.fifo", "Body": "x", "GroupId": "g"}))), "MissingParameter");
}

#[test]
fn delay_and_visibility_timeline() {
    let mut s = Session::new();
    s.create("q", json!({"DelaySeconds": 10, "VisibilityTimeout": 20}));
    send(&mut s, "q", "queue-delay");
    s.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "own-delay", "DelaySeconds": 0}));
    assert_eq!(s.counts("q"), json!({"Visible": 1, "InFlight": 0, "Delayed": 1}));
    assert_eq!(bodies(&receive(&mut s, "q", 10)), ["own-delay"]);
    assert_eq!(s.counts("q"), json!({"Visible": 0, "InFlight": 1, "Delayed": 1}));
    s.tick(10);
    assert_eq!(s.counts("q"), json!({"Visible": 1, "InFlight": 1, "Delayed": 0}));
    s.tick(10);
    // The timed-out message keeps its place in arrival order.
    assert_eq!(bodies(&receive(&mut s, "q", 10)), ["queue-delay", "own-delay"]);
    let again = receive(&mut s, "q", 10);
    assert!(again.is_empty());
}

#[test]
fn receive_parameters_and_visibility_override() {
    let mut s = Session::new();
    s.create("q", json!({}));
    for i in 0..12 {
        send(&mut s, "q", &i.to_string());
    }
    assert_eq!(receive(&mut s, "q", 10).len(), 10);
    assert_eq!(s.err(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 0})), "InvalidParameterValue");
    assert_eq!(s.err(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 11})), "InvalidParameterValue");
    assert_eq!(s.err(json!({"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 43201})), "InvalidParameterValue");
    // VisibilityTimeout 0: visible again at once and the handle is never usable.
    let r = s.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 0}));
    let handle = r["Messages"][0]["ReceiptHandle"].clone();
    assert_eq!(r["Messages"][0]["Body"], "10");
    assert_eq!(s.err(json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": handle})), "ReceiptHandleExpired");
    let r = s.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "10");
    assert_eq!(r["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(r["Messages"][0]["FirstReceivedAt"], 0);
}

#[test]
fn receipt_handles() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.create("other", json!({}));
    send(&mut s, "q", "a");
    send(&mut s, "other", "b");
    let del = |s: &mut Session, q: &str, h: &str| s.send(json!({"Command": "DeleteMessage", "QueueName": q, "ReceiptHandle": h}));
    let code = |r: Value| r["error"]["code"].as_str().unwrap_or("ok").to_owned();

    assert_eq!(code(del(&mut s, "q", "r-1")), "ReceiptHandleInvalid");
    receive(&mut s, "q", 1);
    receive(&mut s, "other", 1);
    for bad in ["r-01", "R-1", "r-1 ", "r-+1", "r-", "1", "r-0", "r-3", "r--1", " r-1", "r-99999999999999999999999"] {
        assert_eq!(code(del(&mut s, "q", bad)), "ReceiptHandleInvalid", "{bad:?}");
    }
    // Issued for another queue.
    assert_eq!(code(del(&mut s, "q", "r-2")), "ReceiptHandleExpired");
    assert_eq!(code(del(&mut s, "nope", "r-1")), "QueueDoesNotExist");
    assert_eq!(code(s.send(json!({"Command": "DeleteMessage", "QueueName": "q"}))), "MissingParameter");
    assert_eq!(code(s.send(json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": 1}))), "InvalidParameterValue");
    // Redelivery supersedes the old handle.
    s.tick(30);
    receive(&mut s, "q", 1);
    assert_eq!(code(del(&mut s, "q", "r-1")), "ReceiptHandleExpired");
    assert_eq!(code(del(&mut s, "q", "r-3")), "ok");
    assert_eq!(code(del(&mut s, "q", "r-3")), "ReceiptHandleExpired");
    assert_eq!(s.counts("q"), json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
